INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.95.0',
  '2026-09-20',
  'Пульт ТВ: дозагрузка в альбом и сборка альбомов из своих треков',
  E'В админке у каждой папки появилась кнопка «📥»: в готовый альбом музыки или в альбом «Фото и видео» можно дозагрузить несколько файлов сразу или целый ZIP-архив. Файл не для этой библиотеки не возьмётся, а одинаковое имя не затрёт старое — рядом появится «(2)».\n\nНовая вкладка «Собрать». Порядок такой: создаёте новый альбом (или папку внутри уже существующего), выбираете, откуда брать треки, слушаете «▶» и добавляете копией «＋» или переносите «→». Можно сразу всю папку — «＋ Все» и «→ Все». Источник меняется сколько угодно, а альбом-приёмник остаётся выбранным.\n\nЗаодно: подпапки альбома («Бонусы», CD1) больше не показываются в каталоге отдельными безымянными плитками — это части одного альбома, и включить их можно по отдельности.',
  E'Агент. upload.go: target=into (один файл) и into-zip (архив) кладут файлы в существующую папку по &id=; допустимость расширения решает вид библиотеки (wanted), занятое имя — freeName «(2)», у архива снимается папка-обёртка, подпапки сохраняются, распаковка по одному файлу (наполовину распакованный архив не страшен, чужое не затирается). transfer.go: POST /api/admin/mkdir {name, id?|kind} — папка внутри папки или в корне библиотеки; POST /api/admin/transfer {ids, to, move} — копия или перенос: rename, а между дисками копия и удаление исходника только после успешной копии; папки, корзина и «уже здесь» пропускаются с причиной; при переносе место в «Продолжить просмотр» едет следом (moveProgress). adminLib получил id — админке нужен корень библиотеки как папка.\n\nmusicTiles: папка с треками — одна плитка (счёт рекурсивный), её подпапки с треками — части (Seasons), обход внутрь не идёт; корень библиотеки по-прежнему обходится, треки прямо в нём — отдельная плитка с названием библиотеки.\n\nСтраница: у папок в админке кнопка «📥» (окно «Файлы / ZIP», несколько файлов загружаются по очереди с прогрессом), вкладка «Собрать» с выбором цели и источника, прослушиванием через отдельный <audio> и кнопками «＋»/«→»/«＋ Все»/«→ Все».\n\nПроверено: TestUploadIntoAlbum (файл, повтор имени, чужой файл, архив с подпапкой, снимок в альбом фото), TestMkdirAndTransfer (создание, занятое имя, папка внутри, копия, перенос, «(2)», «уже здесь», папка и корзина — отказ), TestMusicAlbumMixed, в браузере — весь флоу сборки альбома и дозагрузка файлом и архивом.'
);
